enum Route: Hashable {
  case post(id: String)
  case comment(postID: String, commentID: String)
  case settings
}

@Observable
final class Router {
  var path: [Route] = []
  var pendingAfterLogin: Route?

  func open(_ route: Route, signedIn: Bool) {
    guard signedIn else { pendingAfterLogin = route; return }
    switch route {
    case let .comment(postID, commentID):
      // Rebuild the whole stack at once, not push by push
      path = [.post(id: postID), .comment(postID: postID, commentID: commentID)]
    default:
      path = [route]
    }
  }
}

struct RootView: View {
  @State private var router = Router()

  var body: some View {
    NavigationStack(path: $router.path) {
      FeedView()
        .navigationDestination(for: Route.self) { route in
          switch route {
          case let .post(id): PostView(id: id)
          case let .comment(postID, commentID): CommentView(postID: postID, id: commentID)
          case .settings: SettingsView()
          }
        }
    }
    .onOpenURL { url in
      if let route = RouteParser.parse(url) {
        router.open(route, signedIn: Session.shared.isSignedIn)
      }
    }
  }
}

