// The wording decision lives in the view model, with an injected clock
@Observable
final class CommentRowModel {
  private let comment: Comment
  private let now: () -> Date

  init(comment: Comment, now: @escaping () -> Date = Date.init) {
    self.comment = comment
    self.now = now
  }

  var timestamp: String {
    // the branch is testable; the wording itself is locale-aware
    if now().timeIntervalSince(comment.postedAt) < 7 * 24 * 3600 {
      comment.postedAt.formatted(.relative(presentation: .named))
    } else {
      comment.postedAt.formatted(date: .abbreviated, time: .omitted)
    }
  }
}

