// Right — one property, four states, refresh carried explicitly
enum FeedState: Equatable {
  case idle
  case loading
  case loaded(items: [Item], isRefreshing: Bool)
  case failed(LoadError)
}

@Observable
final class FeedViewModel {
  private(set) var state: FeedState = .idle

  func load(refresh: Bool = false) async {
    if case .loaded(let items, _) = state, refresh {
      state = .loaded(items: items, isRefreshing: true)   // keep the rows
    } else {
      state = .loading
    }
    do { state = .loaded(items: try await repo.feed(), isRefreshing: false) }
    catch { state = .failed(LoadError(error)) }
  }
}

