// The wire format — pessimistic, matches the server exactly
struct PostDTO: Decodable {
  let id: Int
  let author_name: String?
  let created_at: String
  let status: String            // never an enum here

  func toDomain() throws -> Post {
    guard let date = ISO8601DateFormatter().date(from: created_at) else {
      throw MappingError.badDate(created_at)     // fails once, at the boundary
    }
    return Post(
      id: String(id),
      author: author_name ?? "Unknown",
      createdAt: date,
      status: PostStatus(rawValue: status) ?? .unknown  // new server case survives
    )
  }
}

