// Clean Swift scene: VC -> Interactor -> Presenter -> VC, one direction only
protocol OrderBusinessLogic { func fetchOrder(request: Order.Fetch.Request) }
protocol OrderPresentationLogic { func presentOrder(response: Order.Fetch.Response) }
protocol OrderDisplayLogic: AnyObject { func displayOrder(viewModel: Order.Fetch.ViewModel) }

enum Order {                     // three model types per use case
  enum Fetch {
    struct Request { let id: String }
    struct Response { let order: OrderEntity }
    struct ViewModel { let title: String; let total: String; let isLate: Bool }
  }
}

final class OrderInteractor: OrderBusinessLogic, OrderDataStore {
  var order: OrderEntity?       // the data store the next scene reads
  var presenter: OrderPresentationLogic?
  private let worker = OrderWorker()

  func fetchOrder(request: Order.Fetch.Request) {
    Task {
      let order = try await worker.load(id: request.id)
      self.order = order
      presenter?.presentOrder(response: .init(order: order))
    }
  }
}

final class OrderPresenter: OrderPresentationLogic {
  weak var viewController: OrderDisplayLogic?   // weak closes the cycle safely

  func presentOrder(response: Order.Fetch.Response) {
    // every formatting decision is here, and testable without a view
    let vm = Order.Fetch.ViewModel(
      title: response.order.title,
      total: response.order.total.formatted(.currency(code: "USD")),
      isLate: response.order.dueAt < .now
    )
    viewController?.displayOrder(viewModel: vm)
  }
}

