// Data layer — no UI isolation, and explicit about where the work runs
protocol PostRepositoryProtocol: Sendable {
  func posts() async throws -> [Post]
}

struct PostRepository: PostRepositoryProtocol {
  let client: HTTPClient                   // Sendable

  // Wrong: called from a @MainActor view model, this decodes on the main thread
  // func posts() async throws -> [Post] { try await client.get("/posts") }

  // Right: @concurrent runs it on the global executor regardless of the caller
  @concurrent
  func posts() async throws -> [Post] {
    let dtos: [PostDTO] = try await client.get("/posts")
    return try dtos.map { try $0.toDomain() }
  }
}

