actor ImageCache {
  private var storage: [URL: Data] = [:]
  func data(for url: URL) -> Data? { storage[url] }
  func store(_ data: Data, for url: URL) { storage[url] = data }
}

// Wrong — app-wide lifetime, so the next checkout inherits the last one
final class CheckoutDraft { static let shared = CheckoutDraft() }

// Right — the draft's lifetime is the flow's lifetime
@Observable
final class CheckoutDraft {
  var address: Address?
  var payment: PaymentMethod?
  var giftNote: String = ""
}

struct CheckoutFlow: View {
  @State private var draft = CheckoutDraft()   // born with the flow
  @State private var path: [Step] = []
  let onFinish: (Order) -> Void

  enum Step: Hashable { case payment, review }

  var body: some View {
    NavigationStack(path: $path) {
      AddressStep(draft: draft) { path.append(.payment) }
        .navigationDestination(for: Step.self) { step in
          switch step {
          case .payment: PaymentStep(draft: draft) { path.append(.review) }
          case .review:  ReviewStep(draft: draft, onCommit: commit)  // only here
          }
        }
    }
  }

  private func commit() async throws {
    onFinish(try await OrderRepository.live.place(draft))
  }
}

// UIKit equivalent: the coordinator owns the draft and dies with the flow
final class CheckoutCoordinator {
  private let draft = CheckoutDraft()
  private let nav: UINavigationController
  var onCancel: (() -> Void)?          // parent drops this coordinator -> draft freed

  init(nav: UINavigationController) { self.nav = nav }

  func start() {
    nav.setViewControllers([AddressVC(model: .init(draft: draft))], animated: false)
  }
}
